function PropertyRow({p}:{p:Property}){return <div className="property"><div><div className="property-title">{p.address} {p.unit&&<span className="unit">· {p.unit}</span>}</div><div className="property-meta">{p.owner} · {p.tenant||"Sin inquilino"}</div></div><div className="money">{p.rent?money(p.rent):"Sin alquiler"}<small>{p.rent?`Neto ${money(p.rent-chargesTotal(p)-p.rent*p.commission/100)}`:"Completá el valor"}</small></div></div>}
function Kanban({properties,onStatus,onEdit,dragged,setDragged}:{properties:Property[];onStatus:(id:number,s:CollectionStatus)=>void;onEdit:(p:Property)=>void;dragged:number|null;setDragged:(id:number|null)=>void}){const owners=Array.from(new Set(properties.map(p=>p.owner))).sort((a,b)=>a.localeCompare(b,"es"));return <div className="kanban-wrap">{owners.map(owner=>{const list=properties.filter(p=>p.owner===owner),total=list.reduce((s,p)=>s+p.rent,0),net=list.reduce((s,p)=>s+p.rent-chargesTotal(p)-p.rent*p.commission/100,0);return <section className="owner-board" key={owner}><div className="owner-head"><div><h3>{owner}</h3><p>{list.length} unidades · Alquiler {money(total)} · Neto {money(net)}</p></div><span className="pill">Impuestos separados</span></div><div className="kanban-columns">{statuses.map(status=><div className="kanban-column" key={status} onDragOver={e=>e.preventDefault()} onDrop={()=>{if(dragged!==null)onStatus(dragged,status)}}><div className="column-title"><span>{status}</span><b>{list.filter(p=>p.collection===status).length}</b></div>{list.filter(p=>p.collection===status).map(p=><div className={`kanban-card ${dragged===p.id?"dragging":""}`} key={p.id} draggable onDragStart={()=>setDragged(p.id)} onDragEnd={()=>setDragged(null)}><strong>{p.address} {p.unit&&`· ${p.unit}`}</strong><span>{p.tenant||"Sin inquilino"}</span><small>{p.rent?money(p.rent):"Sin alquiler"} · comisión {p.commission}%</small>{p.collection==="Pagado"&&<small className="paid-date">Pagado el {p.paymentDate}</small>}<div className="card-actions"><select value={p.collection} onChange={e=>onStatus(p.id,e.target.value as CollectionStatus)}>{statuses.map(s=><option key={s}>{s}</option>)}</select><button className="button ghost" onClick={()=>onEdit(p)}>Editar</button></div></div>)}</div>)}</div></section>})}</div>}
function EditableTable({properties,owners,update,updateCharge,query,setQuery,ownerFilter,setOwnerFilter,sort,setSort}:{properties:Property[];owners:string[];update:(id:number,key:keyof Property,value:string|number|PaymentRecord[])=>void;updateCharge:(id:number,key:keyof Charges,value:number)=>void;query:string;setQuery:(s:string)=>void;ownerFilter:string;setOwnerFilter:(s:string)=>void;sort:string;setSort:(s:string)=>void}){const [expanded,setExpanded]=useState<number[]>([]);const toggle=(id:number)=>setExpanded(x=>x.includes(id)?x.filter(i=>i!==id):[...x,id]);return <><div className="table-filters"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar dirección, propietario o inquilino"/><select value={ownerFilter} onChange={e=>setOwnerFilter(e.target.value)}><option>Todos</option>{owners.map(o=><option key={o}>{o}</option>)}</select><select value={sort} onChange={e=>setSort(e.target.value)}><option value="owner">Ordenar: propietario</option><option value="address">Ordenar: dirección</option><option value="rent">Ordenar: alquiler mayor</option><option value="collection">Ordenar: estado de cobro</option></select></div><p className="table-hint">Usá “Impuestos” para expandir y editar EPE, Gas, Aguas, TGI, API y Expensas.</p><div className="table-wrap"><table className="editable-table"><thead><tr><th>Impuestos</th><th>Dirección</th><th>Unidad</th><th>Propietario</th><th>Inquilino</th><th>Alquiler</th><th>Total impuestos</th><th>Comisión %</th><th>Estado cobro</th></tr></thead><tbody>{properties.map(p=><><tr key={p.id}><td><button className="expand-button" onClick={()=>toggle(p.id)}>{expanded.includes(p.id)?"Ocultar":"Impuestos"}</button></td><td><input value={p.address} onChange={e=>update(p.id,"address",e.target.value)}/></td><td><input value={p.unit} onChange={e=>update(p.id,"unit",e.target.value)}/></td><td><select value={p.owner} onChange={e=>update(p.id,"owner",e.target.value)}>{owners.map(o=><option key={o}>{o}</option>)}</select></td><td><input value={p.tenant} onChange={e=>update(p.id,"tenant",e.target.value)} placeholder="Sin cargar"/></td><td><input type="number" value={p.rent||""} onChange={e=>update(p.id,"rent",Number(e.target.value)||0)}/></td><td>{money(chargesTotal(p))}</td><td><input className="percent-input" type="number" min="0" step="0.5" value={p.commission} onChange={e=>update(p.id,"commission",Number(e.target.value)||0)}/></td><td><select value={p.collection} onChange={e=>update(p.id,"collection",e.target.value)}>{statuses.map(s=><option key={s}>{s}</option>)}</select></td></tr>{expanded.includes(p.id)&&<tr className="tax-detail-row" key={`${p.id}-taxes`}><td></td><td colSpan={8}><div className="tax-detail"><strong>Detalle de impuestos y expensas</strong>{chargeLabels.map(([key,label])=><label key={key}>{label}<input type="number" value={p.charges[key]||""} onChange={e=>updateCharge(p.id,key,Number(e.target.value)||0)}/></label>)}</div></td></tr>}</>)}</tbody></table></div></>}
function HistoryView({properties,onSavePayment}:{properties:Property[];onSavePayment:(id:number,payment:PaymentRecord)=>void}){
  const monthNames=["Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"]
  const [year,setYear]=useState(String(new Date().getFullYear())),[query,setQuery]=useState(""),[owner,setOwner]=useState("Todos"),[sort,setSort]=useState("owner"),[showNew,setShowNew]=useState(false),[detail,setDetail]=useState<{property:Property;month:string}|null>(null)
  const owners=Array.from(new Set(properties.map(p=>p.owner))).sort((a,b)=>a.localeCompare(b,"es")),months=monthNames.map((_,i)=>`${year}-${String(i+1).padStart(2,"0")}`)
  const visible=properties.filter(p=>(owner==="Todos"||p.owner===owner)&&`${p.address} ${p.unit} ${p.owner} ${p.tenant}`.toLowerCase().includes(query.toLowerCase())).sort((a,b)=>sort==="owner"?a.owner.localeCompare(b.owner,"es")||a.address.localeCompare(b.address,"es"):sort==="address"?a.address.localeCompare(b.address,"es"):b.payments.length-a.payments.length)
  const record=(p:Property,month:string)=>p.payments?.find(r=>r.month===month)
  const [form,setForm]=useState({propertyId:String(properties[0]?.id||""),month:`${year}-${String(new Date().getMonth()+1).padStart(2,"0")}`,status:"Pagado" as CollectionStatus,rent:String(properties[0]?.rent||""),taxes:String(properties[0]?chargesTotal(properties[0]):0),commission:String(properties[0]?properties[0].rent*properties[0].commission/100:0),paidDate:isoToday()})
  const [detailForm,setDetailForm]=useState({rent:"",taxes:"",commission:"",status:"Pendiente" as CollectionStatus,paidDate:""})
  function openDetail(p:Property,month:string){const r=record(p,month);setDetail({property:p,month});setDetailForm({rent:String(r?.rent??p.rent??""),taxes:String(r?.taxes??chargesTotal(p)),commission:String(r?.commission??p.rent*p.commission/100),status:r?.status||"Pendiente",paidDate:r?.paidDate||""})}
  function saveDetail(e:React.FormEvent){e.preventDefault();if(!detail)return;onSavePayment(detail.property.id,{month:detail.month,status:detailForm.status,paidDate:detailForm.status==="Pagado"?(detailForm.paidDate||isoToday()):"",rent:Number(detailForm.rent)||0,taxes:Number(detailForm.taxes)||0,commission:Number(detailForm.commission)||0});setDetail(null)}
  function choose(id:string){const p=properties.find(x=>String(x.id)===id);if(p)setForm({...form,propertyId:id,rent:String(p.rent||""),taxes:String(chargesTotal(p)),commission:String(p.rent*p.commission/100)})}
  function save(e:React.FormEvent){e.preventDefault();const p=properties.find(x=>String(x.id)===form.propertyId);if(!p)return;onSavePayment(p.id,{month:form.month,status:form.status,paidDate:form.status==="Pagado"?(form.paidDate||isoToday()):"",rent:Number(form.rent)||0,taxes:Number(form.taxes)||0,commission:Number(form.commission)||0});setShowNew(false)}
  const totalsForMonth=(month:string)=>visible.reduce((a,p)=>{const r=record(p,month);return {rent:a.rent+(r?.rent||0),taxes:a.taxes+(r?.taxes||0)}},{rent:0,taxes:0})
  return <section className="card history-screen"><div className="section-head"><div><h2>Historial anual</h2><p className="subtitle">Vista de consulta mensual. Seleccioná una celda para ver o editar su detalle.</p></div><div className="history-actions"><label>Año<select value={year} onChange={e=>setYear(e.target.value)}>{[String(new Date().getFullYear()-1),String(new Date().getFullYear()),String(new Date().getFullYear()+1)].map(y=><option key={y}>{y}</option>)}</select></label><button className="button" onClick={()=>setShowNew(!showNew)}>+ Nuevo pago</button></div></div>{showNew&&<form className="payment-form"><h3>Nuevo pago</h3><label>Propiedad<select value={form.propertyId} onChange={e=>choose(e.target.value)}>{properties.map(p=><option key={p.id} value={p.id}>{p.address} {p.unit&&`· ${p.unit}`} — {p.owner}</option>)}</select></label><label>Mes<input type="month" value={form.month} onChange={e=>setForm({...form,month:e.target.value})}/></label><label>Estado<select value={form.status} onChange={e=>setForm({...form,status:e.target.value as CollectionStatus,paidDate:e.target.value==="Pagado"?(form.paidDate||isoToday()):""})}>{statuses.filter(s=>s!=="No alquilada").map(s=><option key={s}>{s}</option>)}</select></label><label>Alquiler cobrado<input type="number" value={form.rent} onChange={e=>setForm({...form,rent:e.target.value})}/></label><label>Impuestos totalizados<input type="number" value={form.taxes} onChange={e=>setForm({...form,taxes:e.target.value})}/></label><label>Comisión<input type="number" value={form.commission} onChange={e=>setForm({...form,commission:e.target.value})}/></label><label>Fecha de cobro<input type="date" value={form.paidDate} onChange={e=>setForm({...form,paidDate:e.target.value})}/></label><div className="form-actions"><button className="button" type="submit">Guardar pago</button><button className="button secondary" type="button" onClick={()=>setShowNew(false)}>Cancelar</button></div></form>}<div className="table-filters"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Filtrar propiedad, propietario o inquilino"/><select value={owner} onChange={e=>setOwner(e.target.value)}><option>Todos</option>{owners.map(o=><option key={o}>{o}</option>)}</select><select value={sort} onChange={e=>setSort(e.target.value)}><option value="owner">Ordenar: propietario</option><option value="address">Ordenar: dirección</option><option value="payments">Ordenar: más pagos registrados</option></select></div><div className="history-table-wrap"><table className="history-table annual-table"><thead><tr><th>Propiedad</th><th>Propietario</th>{monthNames.map(m=><th key={m}>{m}</th>)}</tr></thead><tbody>{visible.map(p=><tr key={p.id}><td><strong>{p.address} {p.unit&&`· ${p.unit}`}</strong><small>{p.tenant||"Sin inquilino"}</small></td><td>{p.owner}</td>{months.map(month=>{const r=record(p,month);return <td key={month}><button className="history-cell-button" onClick={()=>openDetail(p,month)}><strong>{r?money(r.rent):"—"}</strong><span>{r?`Imp. ${money(r.taxes)}`:"Sin carga"}</span><small>{r?.pending?`Pendiente: ${money(r.pending)}`:r?.paidDate?`Cobrado: ${r.paidDate}`:"Ver detalle →"}</small></button></td>})}</tr>)}</tbody><tfoot><tr><th colSpan={2}>Totales</th>{months.map(month=>{const t=totalsForMonth(month);return <th key={month}><strong>{money(t.rent)}</strong><small>Imp. {money(t.taxes)}</small></th>})}</tr></tfoot></table></div>{visible.length===0&&<div className="empty">No hay propiedades que coincidan con el filtro.</div>}{detail&&<div className="detail-overlay"><form className="detail-panel" onSubmit={saveDetail}><div className="section-head"><div><h3>Detalle mensual</h3><p className="subtitle">{detail.property.address} {detail.property.unit&&`· ${detail.property.unit}`} · {detail.month}</p></div><button type="button" className="button ghost" onClick={()=>setDetail(null)}>×</button></div><label>Alquiler cobrado<input type="number" value={detailForm.rent} onChange={e=>setDetailForm({...detailForm,rent:e.target.value})}/></label><label>Impuestos totalizados<input type="number" value={detailForm.taxes} onChange={e=>setDetailForm({...detailForm,taxes:e.target.value})}/></label><label>Comisión<input type="number" value={detailForm.commission} onChange={e=>setDetailForm({...detailForm,commission:e.target.value})}/></label><label>Estado<select value={detailForm.status} onChange={e=>setDetailForm({...detailForm,status:e.target.value as CollectionStatus,paidDate:e.target.value==="Pagado"?(detailForm.paidDate||isoToday()):""})}>{statuses.filter(s=>s!=="No alquilada").map(s=><option key={s}>{s}</option>)}</select></label><label>Fecha de cobro<input type="date" value={detailForm.paidDate} onChange={e=>setDetailForm({...detailForm,paidDate:e.target.value})}/></label><div className="form-actions"><button className="button" type="submit">Guardar cambios</button><button className="button secondary" type="button" onClick={()=>setDetail(null)}>Cancelar</button></div></form></div>}</section>
}
function PaymentHistory({p,onChange}:{p:Property;onChange:(payments:PaymentRecord[])=>void}){const records=[...(p.payments||[])].sort((a,b)=>b.month.localeCompare(a.month));const add=()=>{const month=currentMonth();if(records.some(r=>r.month===month))return;onChange([...(p.payments||[]),{month,status:"Pendiente",paidDate:"",rent:p.rent,taxes:chargesTotal(p),commission:p.rent*p.commission/100}])};const edit=(record:PaymentRecord,key:keyof PaymentRecord,value:string|number)=>{const next=(p.payments||[]).map(r=>r.month===record.month?{...r,[key]:value,...(key==="status"?{paidDate:value==="Pagado"?(r.paidDate||today()):""}:{})}:r);onChange(next)};const totalRent=records.reduce((s,r)=>s+r.rent,0),totalTaxes=records.reduce((s,r)=>s+r.taxes,0),totalCommission=records.reduce((s,r)=>s+r.commission,0),totalNet=totalRent-totalTaxes-totalCommission;return <div className="payment-history"><div className="payment-history-head"><strong>Seguimiento mensual</strong><span>Alquiler: {money(totalRent)} · Impuestos: {money(totalTaxes)} · Comisión: {money(totalCommission)} · Neto: {money(totalNet)}</span><button className="button secondary" type="button" onClick={add}>+ Mes actual</button></div>{records.length===0?<small className="table-hint">Todavía no hay meses registrados. Al mover la tarjeta a Pagado se crea el mes automáticamente.</small>:<div className="payment-list">{records.map(r=><div className="payment-row" key={r.month}><input type="month" value={r.month} onChange={e=>edit(r,"month",e.target.value)}/><select value={r.status} onChange={e=>edit(r,"status",e.target.value as CollectionStatus)}>{statuses.map(s=><option key={s}>{s}</option>)}</select><input type="number" value={r.rent||""} onChange={e=>edit(r,"rent",Number(e.target.value)||0)} placeholder="Alquiler"/><span>Imp. {money(r.taxes)} · Com. {money(r.commission)}</span><strong>Neto {money(r.rent-r.taxes-r.commission)}</strong>{r.status==="Pagado"&&<small className="paid-date">Pagado: {r.paidDate}</small>}</div>)}</div>}</div>}
function MovementForm({properties,settings,onSave,onCancel}:{properties:Property[];settings:AgencySettings;onSave:(movement:Movement|Movement[])=>void;onCancel:()=>void}){const [form,setForm]=useState({date:isoToday(),propertyId:"",kind:"Gastos administrativos" as Movement["kind"],concept:"",amount:"",notes:"",contractTotal:"",contractPercent:String(settings.contractFeePercent),installments:"1",stamp:"",firstRent:"",initialTaxes:""});const p=properties.find(x=>String(x.id)===form.propertyId);function base(partial:Partial<Movement>):Movement{return {id:Date.now()+Math.floor(Math.random()*1000),date:form.date,propertyId:p?.id,property:p?`${p.address} ${p.unit}`:"",owner:p?.owner||"",tenant:p?.tenant||"",kind:form.kind,concept:form.concept,amount:Number(form.amount)||0,applied:0,notes:form.notes,...partial}}function save(e:React.FormEvent){e.preventDefault();if(form.kind==="Gastos de ingreso"&&p){const contract=Number(form.contractTotal)||0,percent=Number(form.contractPercent)||5,installments=Math.max(1,Number(form.installments)||1),fee=contract*percent/100,items:Movement[]=[];for(let i=1;i<=installments;i++)items.push(base({kind:"Gastos de contrato",concept:`Gastos de contrato · cuota ${i}/${installments}`,amount:fee/installments,notes:`${percent}% de contrato por ${money(contract)}`}));if(Number(form.stamp)>0)items.push(base({kind:"Sellados",concept:"Sellados de ingreso",amount:Number(form.stamp),notes:form.notes}));if(Number(form.firstRent)>0||Number(form.initialTaxes)>0)items.push(base({kind:"Cobro alquiler",concept:"Primer mes e impuestos de ingreso",amount:(Number(form.firstRent)||0)+(Number(form.initialTaxes)||0),notes:`Alquiler: ${money(Number(form.firstRent)||0)} · Impuestos: ${money(Number(form.initialTaxes)||0)}`}));onSave(items);return}onSave(base({amount:Number(form.amount)||0}))}return <form className="form movement-form" onSubmit={save}><div className="section-head"><div><h2>Nuevo movimiento</h2><p className="subtitle">Registrá cobros, gastos, créditos o movimientos generales.</p></div></div><label>Fecha<input type="date" value={form.date} onChange={e=>setForm({...form,date:e.target.value})}/></label><label>Tipo<select value={form.kind} onChange={e=>setForm({...form,kind:e.target.value as Movement["kind"]})}><option>Cobro alquiler</option><option>Pago Propietario</option><option>Gasto extraordinario pagado por inquilino</option><option>Gasto extraordinario pagado por Inmobiliaria</option><option>Gasto extraordinario a cobrar</option><option>Gastos administrativos</option><option>Gastos de contrato</option><option>Sellados</option><option>Viáticos</option><option>Gastos de ingreso</option><option>Otro</option></select></label><label>Propiedad / alquiler<select value={form.propertyId} onChange={e=>setForm({...form,propertyId:e.target.value})}><option value="">Movimiento general</option>{properties.map(p=><option key={p.id} value={p.id}>{p.address} {p.unit&&`· ${p.unit}`} — {p.tenant||p.owner}</option>)}</select></label>{form.kind==="Gastos de ingreso"?<><label>Valor total del contrato<input required type="number" min="0" value={form.contractTotal} onChange={e=>setForm({...form,contractTotal:e.target.value})}/></label><label>Gastos de contrato (%)<input type="number" min="0" step="0.5" value={form.contractPercent} onChange={e=>setForm({...form,contractPercent:e.target.value})}/></label><label>Cuotas<input type="number" min="1" value={form.installments} onChange={e=>setForm({...form,installments:e.target.value})}/></label><label>Sellados<input type="number" min="0" value={form.stamp} onChange={e=>setForm({...form,stamp:e.target.value})}/></label><label>Primer mes de alquiler<input type="number" min="0" value={form.firstRent} onChange={e=>setForm({...form,firstRent:e.target.value})}/></label><label>Impuestos iniciales<input type="number" min="0" value={form.initialTaxes} onChange={e=>setForm({...form,initialTaxes:e.target.value})}/></label><div className="commission-note">Se generarán {form.installments||1} cuota(s) de gastos de contrato por <strong>{money(((Number(form.contractTotal)||0)*(Number(form.contractPercent)||5)/100)/(Number(form.installments)||1))}</strong>.</div></>:<><label>Concepto<input required value={form.concept} onChange={e=>setForm({...form,concept:e.target.value})} placeholder="Ej. Reparación, transferencia o gasto"/></label><label>Importe<input required type="number" min="0" value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})}/></label></>}<label>Notas<input value={form.notes} onChange={e=>setForm({...form,notes:e.target.value})}/></label>{form.kind==="Gasto extraordinario pagado por inquilino"&&<div className="commission-note">Este importe quedará como crédito para descontarlo de próximos alquileres.</div>}{form.kind==="Gasto extraordinario a cobrar"&&<div className="commission-note">Este importe quedará pendiente para sumarse al próximo cobro del inquilino.</div>}<div className="form-actions"><button className="button" type="submit">Guardar movimiento</button><button className="button secondary" type="button" onClick={onCancel}>Cancelar</button></div></form>}
function CollectionForm({properties,movements,creditAvailable,extraordinaryDue,settings,monthCloses,onSave,onCancel,onHistory}:{properties:Property[];movements:Movement[];creditAvailable:(id:number)=>number;extraordinaryDue:(id:number)=>number;settings:AgencySettings;monthCloses:Record<string,MonthClose>;onSave:(id:number,payment:PaymentRecord,credit:number,extra:number)=>void;onCancel:()=>void;onHistory:()=>void}){const first=properties[0];const [form,setForm]=useState({propertyId:String(first?.id||""),month:currentMonth(),payerName:first?.tenant||"",rent:String(first?.rent||""),taxes:String(first?chargesTotal(first):0),commission:String(first?first.rent*first.commission/100:0),extraordinary:String(first?extraordinaryDue(first.id):0),creditApplied:"0",amountReceived:String((first?.rent||0)+(first?chargesTotal(first):0)+(first?extraordinaryDue(first.id):0)),paidDate:isoToday()});const [saved,setSaved]=useState<{property:Property;payment:PaymentRecord}|null>(null);const selected=properties.find(p=>String(p.id)===form.propertyId)||first;const monthClosed=monthCloses[form.month]?.status==="Cerrado",extraDue=selected?extraordinaryDue(selected.id):0,due=(Number(form.rent)||0)+(Number(form.taxes)||0)+extraDue,available=selected?creditAvailable(selected.id):0;function choose(id:string){const p=properties.find(x=>String(x.id)===id);if(p){const total=p.rent+chargesTotal(p)+extraordinaryDue(p.id),credit=creditAvailable(p.id);setForm({...form,propertyId:id,payerName:p.tenant,rent:String(p.rent||""),taxes:String(chargesTotal(p)),extraordinary:String(extraordinaryDue(p.id)),commission:String(p.rent*p.commission/100),creditApplied:String(Math.min(credit,total)),amountReceived:String(Math.max(0,total-Math.min(credit,total)))})}}function save(){if(!selected)return;const credit=Math.min(Math.max(0,Number(form.creditApplied)||0),available,due);const received=Math.min(Math.max(0,Number(form.amountReceived)||0),Math.max(0,due-credit));const pending=Math.max(0,due-credit-received);const extraApplied=Math.min(extraDue,Math.max(0,received));const payment:PaymentRecord={month:form.month,status:pending===0?"Pagado":"Pendiente",paidDate:pending===0?(form.paidDate||isoToday()):"",rent:Number(form.rent)||0,taxes:Number(form.taxes)||0,commission:Number(form.commission)||0,payerName:form.payerName,receiptNumber:`RC-${Date.now().toString().slice(-6)}`,ownerPaid:false,ownerPaidDate:"",discount:credit,collected:received,pending,extraordinary:extraDue};onSave(selected.id,payment,credit,extraApplied);setSaved({property:selected,payment})}function printReceipt(kind:"tenant"|"owner"){if(!saved)return;const {property,payment}=saved;const commission=payment.commission,total=payment.rent+payment.taxes,received=payment.collected??total-(payment.discount||0),net=total-commission;const title=kind==="tenant"?"Comprobante de cobro al inquilino":"Liquidación al propietario";const recipient=kind==="tenant"?(payment.payerName||property.tenant||"Inquilino"):(property.owner||"Propietario");const html=`<html><head><title>${title}</title><style>body{font-family:Arial,sans-serif;padding:40px;color:#18231f}h1{font-size:24px}table{width:100%;border-collapse:collapse;margin:24px 0}td{padding:10px;border-bottom:1px solid #ddd}.total{font-size:18px;font-weight:bold}small{color:#667}</style></head><body><h1>${settings.name||"Inmobiliaria"}</h1><p>${settings.legalName||""} ${settings.cuit?"· CUIT "+settings.cuit:""}</p><p>${settings.address||""} ${settings.phone?"· "+settings.phone:""} ${settings.email?"· "+settings.email:""}</p><hr/><h2>${title}</h2><small>${payment.receiptNumber||"Comprobante"} · ${payment.month}</small><h3>${recipient}</h3><p>${property.address} ${property.unit?"· "+property.unit:""}</p><table><tr><td>Alquiler</td><td>${money(payment.rent)}</td></tr><tr><td>Impuestos y expensas</td><td>${money(payment.taxes)}</td></tr><tr><td>Descuento aplicado</td><td>- ${money(payment.discount||0)}</td></tr><tr><td>Comisión inmobiliaria</td><td>${kind==="owner"?"- "+money(commission):money(commission)}</td></tr><tr class="total"><td>${kind==="tenant"?"Total recibido":"Total a pagar al propietario"}</td><td>${money(kind==="tenant"?received:net)}</td></tr></table><p>Fecha de cobro: ${payment.paidDate||"Pendiente"}</p><small>Comprobante interno. No constituye factura o comprobante fiscal.</small><script>window.onload=()=>window.print()</script></body></html>`;const win=window.open("","_blank","width=760,height=900");if(win){win.document.write(html);win.document.close()}}return <section className="card collection-panel"><div className="section-head"><div><h2>Nuevo cobro</h2><p className="subtitle">Registrá el cobro, aplicá créditos y generá los comprobantes.</p></div><button className="button ghost" onClick={onCancel}>Cerrar</button></div>{saved?<div className="collection-success"><h3>Cobro registrado</h3><p>{saved.property.address} · Mes: <strong>{saved.payment.month}</strong> · Recibido: {money(saved.payment.collected||0)} · Pendiente: {money(saved.payment.pending||0)}</p><div className="form-actions"><button className="button" onClick={()=>printReceipt("tenant")}>Imprimir comprobante inquilino</button><button className="button secondary" onClick={()=>printReceipt("owner")}>Imprimir liquidación propietario</button><button className="button ghost" onClick={onHistory}>Ver historial mensual</button></div><p className="table-hint">El pago al propietario queda pendiente hasta marcarlo como pagado desde Propietarios.</p></div>:<form className="collection-form"><label>Propiedad<select value={form.propertyId} onChange={e=>choose(e.target.value)}>{properties.map(p=><option key={p.id} value={p.id}>{p.address} {p.unit&&`· ${p.unit}`} — {p.owner}</option>)}</select></label><label>Inquilino / pagador<input value={form.payerName} onChange={e=>setForm({...form,payerName:e.target.value})} placeholder="Nombre del inquilino"/></label><label>Mes de cobro (actual por defecto)<input type="month" value={form.month} onChange={e=>setForm({...form,month:e.target.value})}/></label><label>Fecha de cobro<input type="date" value={form.paidDate} onChange={e=>setForm({...form,paidDate:e.target.value})}/></label><label>Alquiler cobrado<input type="number" value={form.rent} onChange={e=>{const rent=e.target.value;setForm({...form,rent,commission:String((Number(rent)||0)*(selected?.commission||0)/100)})}}/></label><label>Impuestos y expensas totalizados<input type="number" value={form.taxes} onChange={e=>setForm({...form,taxes:e.target.value})}/></label><label>Gastos extraordinarios pendientes<input type="number" value={form.extraordinary} readOnly/><small className="field-help">Se suman automáticamente al próximo cobro.</small></label><label>Crédito disponible del inquilino<input type="number" min="0" max={Math.min(available,due)} value={form.creditApplied} onChange={e=>setForm({...form,creditApplied:e.target.value})}/><small className="field-help">Disponible: {money(available)}</small></label><label>Importe recibido<input type="number" min="0" max={Math.max(0,due-(Number(form.creditApplied)||0))} value={form.amountReceived} onChange={e=>setForm({...form,amountReceived:e.target.value})}/></label><label>Comisión inmobiliaria ({selected?.commission||0}%)<input type="number" value={form.commission} onChange={e=>setForm({...form,commission:e.target.value})}/></label>{selected?.payments.some(p=>p.month===form.month)&&<div className="duplicate-warning">Ya existe un cobro para este mes. Al guardar lo actualizarás.</div>}<div className="commission-note">Total: <strong>{money(due)}</strong> · Aplicado por crédito: <strong>{money(Math.min(Number(form.creditApplied)||0,available))}</strong> · Pendiente: <strong>{money(Math.max(0,due-(Number(form.creditApplied)||0)-(Number(form.amountReceived)||0)))}</strong></div><div className="form-actions">{monthClosed&&<div className="commission-note">Este mes está cerrado. Reabrilo desde `Cierres` para modificarlo.</div>}<button className="button primary-cta" type="button" disabled={monthClosed} onClick={save}>Registrar cobro</button><button className="button secondary" type="button" onClick={onCancel}>Cancelar</button></div></form>}</section>}
function PropertyForm({form,setForm,editing,onSave,onCancel}:{form:{address:string;unit:string;owner:string;tenant:string;rent:string;commission:string;status:Property["status"];collection:CollectionStatus;paymentDate:string;charges:Charges};setForm:React.Dispatch<React.SetStateAction<typeof form>>;editing:Property|null;onSave:(e:React.FormEvent)=>void;onCancel:()=>void}){return <form className="form" onSubmit={onSave}><h2>{editing?"Editar propiedad":"Agregar propiedad"}</h2><label>Dirección<input required value={form.address} onChange={e=>setForm({...form,address:e.target.value})}/></label><label>Piso / departamento / local<input value={form.unit} onChange={e=>setForm({...form,unit:e.target.value})}/></label><label>Propietario<select value={form.owner} onChange={e=>setForm({...form,owner:e.target.value})}>{ownerNames.map(o=><option key={o}>{o}</option>)}</select></label><label>Inquilino<input value={form.tenant} onChange={e=>setForm({...form,tenant:e.target.value})}/></label><label>Alquiler mensual<input type="number" value={form.rent} onChange={e=>setForm({...form,rent:e.target.value})}/></label><div className="tax-detail form-taxes"><strong>Impuestos y expensas</strong>{chargeLabels.map(([key,label])=><label key={key}>{label}<input type="number" value={form.charges[key]||""} onChange={e=>setForm({...form,charges:{...form.charges,[key]:Number(e.target.value)||0}})}/></label>)}</div><label>Comisión (%)<input type="number" min="0" step="0.5" value={form.commission} onChange={e=>setForm({...form,commission:e.target.value})}/></label><label>Estado de cobro<select value={form.collection} onChange={e=>setForm({...form,collection:e.target.value as CollectionStatus})}>{statuses.map(s=><option key={s}>{s}</option>)}</select></label><label>Estado del inmueble<select value={form.status} onChange={e=>setForm({...form,status:e.target.value as Property["status"]})}><option>Alquilada</option><option>Disponible</option></select></label><div className="commission-note">Valor base: <strong>10%</strong>. Se puede modificar por propiedad.</div><div className="form-actions"><button className="button" type="submit">Guardar</button><button className="button secondary" type="button" onClick={onCancel}>Cancelar</button></div></form>}
